css:
.p21-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p21-page > .deck { grid-row: 2; align-self: center; }
.p21-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p21-top:empty { display: none; }
.p21-strip { --p21-sh: 9rem; }
.p21-strip--b { --p21-sh: 4.5rem; }
.p21-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p21-sh)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p21-strip { --p21-sh: 17rem; } .p21-strip--b { --p21-sh: 6rem; } }
@media (max-width: 21.25rem) { .p21-strip { --p21-sh: 22rem; } .p21-strip--b { --p21-sh: 7rem; } }
.p21-win .deck-card__head { margin-top: 0; }
.p21-face { gap: var(--s-2); }
.p21-body { flex: 1 1 auto; min-height: 0; overflow: auto; display: grid; grid-auto-rows: min-content; gap: var(--s-3); align-content: start; padding-block: var(--s-1) var(--s-2); border-bottom: var(--w1) solid var(--rule); }
.p21-msg { flex: none; display: grid; gap: var(--s-2); }
.p21-msg:empty { display: none; }
.p21-foot { flex: none; display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--s-2); }
.dialog__foot.p21-foot2 { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); }
.p21-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -1); }
.p21-area { position: relative; }
.p21-count { position: absolute; right: var(--s-2); bottom: var(--s-1); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); pointer-events: none; background: var(--white); padding-inline: var(--s-1); }
.p21-count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.textarea.p21-ta { min-height: 4rem; padding-bottom: 1.375rem; resize: none; }
.p21-pair { display: grid; grid-template-columns: repeat(auto-fit, minmax(9.5rem, 1fr)); gap: var(--s-3); align-items: start; }
.p21-pair .field { grid-template-columns: minmax(0, 1fr); }
.p21-pair .select { height: auto; min-width: 0; padding-block: var(--s-2); }
.p21-pair .select > span { min-width: 0; flex: 1 1 auto; overflow: hidden; overflow-wrap: anywhere; }
.p21-pair .select .motive { display: flex; max-width: 100%; }
.p21-pair + .menu { margin-top: calc(var(--s-2) * -1); }
.p21-full { grid-column: 1 / -1; }
.textarea.p21-name { min-height: var(--ctl-h); padding: var(--s-2) var(--s-3); resize: none; overflow-wrap: anywhere; }
.btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p21-tipw { position: relative; display: flex; min-width: 0; }
.p21-tipw > .btn { flex: 1 1 auto; width: 100%; }
.p21-tip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.p21-win .hint { font-size: var(--fs-small); }
.p21-fade { opacity: 0.5; }
.p21-pressed { border-width: var(--w2); border-color: var(--ink); text-decoration: underline; text-underline-offset: 0.25em; }

.dialog.p21-dlg { max-height: 100%; }
.dialog__foot.p21-foot3 { flex-direction: column; }
.dialog__foot.p21-foot3 > * { flex: none; }
.p21-dlg .dialog__body p + p { color: var(--muted); }
.p21-dlg .banner { padding-inline: var(--s-3); }
.p21-dlg .dialog__foot .p21-tipw { position: relative; }
.p21-dtip { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }

.p21-above { display: contents; }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.deck__stack:has(> .p21-win) { width: min(var(--card-max), calc(100cqw - 2rem)); height: auto; }
.deck__stack:has(> .p21-win) ~ .deck__controls { display: none; }
.p21-win { position: relative; left: auto; bottom: auto; width: 100%; height: auto; min-height: var(--card-min); max-height: calc(100cqh - 2rem - var(--p21-win-off, 0rem)); display: flex; flex-direction: column; }
.p21-win .deck-card__face { position: relative; inset: auto; flex: 1 1 auto; min-height: 0; }
.p21-win [class*="-body"], .p21-win .deck-card__scroll { scrollbar-width: thin; scrollbar-color: var(--line) var(--white); }
.p21-strip { --p21-win-off: 9.5rem; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p21-strip { --p21-win-off: 19.5rem; } }
@media (max-width: 21.25rem) { .p21-strip { --p21-win-off: 29.5rem; } }
.p21-strip.p21-strip--b { --p21-win-off: 5.5rem; }
@media (max-width: 21.25rem) { .p21-strip.p21-strip--b { --p21-win-off: 8rem; } }
.p21-body { scroll-snap-type: y mandatory; }
.p21-above + * { scroll-snap-align: start; }
.p21-count { position: static; display: block; text-align: right; padding: 0; background: none; pointer-events: auto; }
.textarea.p21-ta { padding-bottom: var(--s-2); }
.p21-area { display: grid; gap: var(--s-1); }
.p21-foot:has(.p21-tipw) { grid-auto-flow: row; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
.p21-foot .p21-tipw { display: contents; }
.p21-foot .p21-tipw > .tip { position: static; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; order: 3; }

.p21-dlg .dialog__foot:has(.p21-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p21-dlg .dialog__foot .p21-tipw { display: contents; }
.p21-dlg .dialog__foot .p21-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p21-dlg .dialog__head { flex-wrap: wrap; }
  .p21-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p21-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }
.p21-draft { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }

.p21-sw { display: grid; gap: var(--s-2); }
.p21-sw .swatches { max-width: calc(6 * var(--hit) + 5 * var(--s-2)); }
.p21-swname { display: flex; align-items: center; gap: var(--s-2); min-height: var(--s-4); margin: 0; }
.p21-swname .mdot { width: 1rem; height: 1rem; }
.p21-hint { margin: 0; color: var(--muted); font-size: var(--fs-cap); line-height: var(--lh-cap); }
.swatch:disabled { cursor: not-allowed; }
.swatch:disabled::before { border-color: var(--c-disabled-border); }
